class Solution {
  private int[] walls;

  private int count(long lo, long hi) {
    if (hi < lo) return 0;
    return upper(hi) - upper(lo - 1);
  }

  // number of walls <= x
  private int upper(long x) {
    int lo = 0, hi = walls.length;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (walls[mid] <= x) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }

  public int maxWalls(int[] robots, int[] distance, int[] wallsIn) {
    walls = wallsIn.clone();
    java.util.Arrays.sort(walls);
    int n = robots.length;
    long[] keyed = new long[n];
    for (int i = 0; i < n; i++) keyed[i] = (long) robots[i] * 200_000 + i;
    java.util.Arrays.sort(keyed);
    long[] r = new long[n], d = new long[n];
    for (int i = 0; i < n; i++) {
      int id = (int) (keyed[i] % 200_000);
      r[i] = robots[id];
      d[i] = distance[id];
    }
    int base = 0;
    for (int i = 0; i < n; i++) base += count(r[i], r[i]);
    long[] dp = new long[2]; // dp[0]: robot shoots left, dp[1]: shoots right
    dp[0] = count(r[0] - d[0], r[0] - 1);
    dp[1] = 0;
    for (int i = 0; i + 1 < n; i++) {
      long a1 = r[i] + 1, b1 = Math.min(r[i] + d[i], r[i + 1] - 1);
      long a2 = Math.max(r[i + 1] - d[i + 1], r[i] + 1), b2 = r[i + 1] - 1;
      int right = count(a1, b1), left = count(a2, b2);
      int both = a2 <= b1 ? count(a1, Math.max(b1, b2)) : right + left;
      long[] nd = new long[2];
      // next robot left (index 0) or right (index 1)
      nd[0] = Math.max(dp[0] + left, dp[1] + both);
      nd[1] = Math.max(dp[0], dp[1] + right);
      dp = nd;
    }
    long last = Math.max(dp[0], dp[1] + count(r[n - 1] + 1, r[n - 1] + d[n - 1]));
    return (int) (last + base);
  }
}
